import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';

const ConsulterCV = () => {
    const { id } = useParams();
    const [cvData, setCvData] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Appel à ton API backend
        fetch(`http://localhost:5000/api/candidature/${id}`)
            .then(res => res.json())
            .then(data => {
                setCvData(data);
                setLoading(false);
            })
            .catch(err => {
                console.error("Erreur chargement CV :", err);
                setLoading(false);
            });
    }, [id]);

    if (loading) return <div>Chargement du CV...</div>;
    if (!cvData) return <div>CV introuvable.</div>;

    return (
        <div style={{ padding: '20px' }}>
            <h1>Consultation du CV : {cvData.fileName}</h1>
            
            <div style={{ marginTop: '20px', border: '1px solid #ccc', height: '800px' }}>
                {/* Si cvBase64 est une image (PNG/JPG), src est suffisant.
                   Si c'est un PDF en base64, l'iframe l'affichera aussi correctement.
                */}
                <iframe 
                    src={cvData.cvBase64} 
                    title="CV Candidat"
                    width="100%" 
                    height="100%" 
                />
            </div>
            
            <a 
                href={cvData.cvBase64} 
                download={cvData.fileName}
                style={{ display: 'block', marginTop: '10px' }}
            >
                Télécharger le fichier original
            </a>
        </div>
    );
};

export default ConsulterCV;
